        c.multiplicate{value: padding}(address(this));

        uint preBalC = address(c).balance;
        uint preBalSelf = address(this).balance;

        bool reverted;
        try c.multiplicate{value: amount}(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint postBalC = address(c).balance;

        assert(reverted || postBalC == preBalSelf - (amount / 2));
    }

    receive() external payable {}
}
